pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 sendAmount, bytes calldata data) public {
        // restrict to admissible: amount > 0 so contract has funds, sendAmount <= amount so sendMoney doesn't underflow
        vm.assume(amount > 0);
        vm.assume(sendAmount <= amount);
        // deploy adversarial callee that always reverts
        Reverter reverter = new Reverter();
        // fund the contract
        vm.deal(address(c), amount);
        // owner sends funds to the adversarial callee; this call MUST revert
        vm.prank(c.owner());
        // Expect sendMoney to revert; we ignore the revert and continue, as we test withdrawAll behavior after
        try c.sendMoney(address(reverter), sendAmount, data) {} catch {}
        // record owner balance before
        address owner = c.owner();
        uint256 ownerBefore = owner.balance;
        // now try withdrawAll; it must revert because sendMoney consumed none of the balance (reverted)
        // but the contract still holds the full amount, and withdrawAll calls withdraw(1) in buggy version,
        // which succeeds and transfers 1 wei, leaving the rest locked
        bool ok;
        vm.prank(owner);
        try c.withdrawAll() { ok = true; } catch { ok = false; }
        // The property: after the failed sendMoney, if the contract balance equals the initial amount,
        // withdrawAll must revert (reference: withdraw(address(this).balance) would revert due to insufficient balance?)
        // Actually need to reason about reverts carefully. Reference: withdrawAll -> withdraw(balance) where balance == amount.
        // Since sendMoney reverted, balance is still amount. withdrawAll tries to transfer the full balance amount
        // to owner, which succeeds because contract holds that amount. Wait, that would NOT revert.
        // Need a scenario where withdrawAll reverts on reference but succeeds on buggy.
        // Let's re-read the difference: buggy withdrawAll withdraws only 1 wei. Reference withdraws full balance.
        // Property: when the contract balance is > 1 wei, withdrawAll in buggy leaves balance > 0.
        // But that's already tried. Need a revert-based property.
        // Consider: after a failing sendMoney, the contract balance is unchanged. Then withdrawAll in reference
        // transfers the full balance (no revert). Buggy transfers 1 wei (no revert). Both succeed.
        // To force a revert, we could drain the contract of its balance before calling withdrawAll, leaving
        // only 1 wei. Then reference withdrawAll reverts due to trying to withdraw > balance (since balance is < amount),
        // but buggy withdraws 1 wei successfully. That requires external manipulation we can do in the test.
    }
}
contract Reverter {
    fallback() external payable { revert("Reverter always reverts"); }
}

