pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        vm.assume(amount > 0 && amount <= 100 ether);
        vm.assume(actor != c.owner());

        vm.deal(address(c), amount);
        uint256 balanceBefore = address(c).balance;

        bool calledWithdrawAll;
        vm.prank(actor);
        try c.withdrawAll() { calledWithdrawAll = true; } catch { calledWithdrawAll = false; }

        if (calledWithdrawAll) {
            // If the call succeeded, the contract balance must have decreased by amount (sent to actor).
            // But in the reference, the call should never succeed for a non-owner.
            // This assertion will pass vacuously in the reference (call never succeeds),
            // and will fail in the buggy version when the call succeeds and balance is drained.
            assertTrue(address(c).balance < balanceBefore);
        } else {
            // If the call reverted, the balance must be unchanged.
            assertTrue(address(c).balance == balanceBefore);
        }
    }
}

