pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, bytes memory data) public {
        vm.assume(amount <= address(this).balance);
        vm.assume(data.length >= 4);

        // Deploy an adversarial helper that will increment depositsCount via delegatecall in C's context
        DepositsIncrementer incrementer = new DepositsIncrementer();

        // Record depositsCount before the call
        uint256 depositsBefore = c.depositsCount();

        // Fund the contract with some ether so that balance checks are irrelevant
        vm.deal(address(c), amount);

        // Call sendMoney with the attacker's address
        c.sendMoney(address(incrementer), amount, data);

        // The property: depositsCount must not change after sendMoney
        uint256 depositsAfter = c.depositsCount();
        assertTrue(depositsAfter == depositsBefore);
    }
}

contract DepositsIncrementer {
    // This function will be delegatecalled in C's context.
    // Its selector is 0xa4f0d7ae -> incrementDeposits()
    function incrementDeposits() external {
        // In delegatecall context, this modifies C's depositsCount
        // We need to directly write to the storage slot of depositsCount (slot 1) because
        // we cannot access C's type here. But we can use inline assembly to increment slot 1.
        assembly {
            let slot := 1
            sstore(slot, add(sload(slot), 1))
        }
    }
}

