pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _value, bytes memory _data) public {
        // Restrict value to a reasonable range to avoid overflow constraints
        bound(_value, 1, 100 ether);
        // Deploy an adversarial reverter to prevent successful Ether forwarding
        Reverter reverter = new Reverter();
        // Fund C with enough Ether to attempt the transfer
        vm.deal(address(c), _value);
        // Record the balance before the call
        uint256 balanceBefore = address(c).balance;
        // Owner initiates sendMoney to the reverter contract
        vm.prank(c.owner());
        c.sendMoney(address(reverter), _value, _data);
        // After the call, balance should have decreased by _value if Ether was actually sent
        assertTrue(address(c).balance == balanceBefore - _value);
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}
